class Calculator:
    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        if b == 0:
            raise ValueError('Division by zero')
        return a / b

    def power(self, base, exp):
        return base ** exp

def custom_sort(items, key=None, reverse=False):
    '''Sort items with custom key function.'''
    return sorted(items, key=key, reverse=reverse)

def filter_range(items, min_val=None, max_val=None):
    '''Filter items within range.'''
    result = items
    if min_val is not None:
        result = [x for x in result if x >= min_val]
    if max_val is not None:
        result = [x for x in result if x <= max_val]
    return result

def unique(items):
    '''Return unique items preserving order.'''
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

class UserRepository:
    def __init__(self, db_url, cache_url):
        self.db = connect(db_url)
        self.cache = Redis(cache_url)

    def get_user(self, user_id):
        # Try cache first
        cached = self.cache.get(f'user:{user_id}')
        if cached:
            return json.loads(cached)

        # Query database
        user = self.db.query('SELECT * FROM users WHERE id = ?', user_id)
        if user:
            self.cache.setex(f'user:{user_id}', 300, json.dumps(user))
        return user

    def create_user(self, data):
        user = self.db.execute(
            'INSERT INTO users (name, email) VALUES (?, ?)',
            data['name'], data['email']
        )
        return user

    def invalidate_cache(self, user_id):
        self.cache.delete(f'user:{user_id}')

def process_data(data, options=None):
    options = options or {}

    if not data:
        return {'error': 'No data provided'}

    result = []
    for item in data:
        if options.get('skip_none') and item is None:
            continue

        if options.get('transform'):
            item = options['transform'](item)

        if options.get('filter'):
            if not options['filter'](item):
                continue

        result.append(item)

    if options.get('sort'):
        result.sort(key=options.get('sort_key'))

    if options.get('limit'):
        result = result[:options['limit']]

    return {'data': result, 'count': len(result)}
